mapper.insert:
insert into STUDENT(
	SCHOOL_CODE, NAME, GRADE, SEMESTER, TRACK
) VALUES (
	#{schoolCode}, #{name}, #{grade}, #{semester}, #{track}
)

mapper.select:
select
	C.STUDENT_NO
	,C.NAME
	,C.GRADE
	,C.SEMESTER
	,C.TRACK
	,C.SCHOOL_NAME
	,T.MAJOR
	,T.UNIV
	,T.RANKING
from(
	select B.*
	from(
		select ROWNUM AS RN, A.*
		from(
			select
				S.STUDENT_NO
				,S.NAME
				,S.GRADE
				,S.SEMESTER
				,S.TRACK
				,SCH.NAME AS SCHOOL_NAME
			from STUDENT S
			left join SCHOOL SCH on (S.SCHOOL_CODE = SCH.SCHOOL_CODE)


					AND S.NAME = #{name}


					AND S.GRADE = #{grade}


					AND S.SEMESTER = #{semester}


					AND S.TRACK = #{track}


					AND SCH.NAME = #{schoolName}


					and exist(
						select 1
						from TARGET_INFO T2
						inner join STUDENT S2 on(T2.STUDENT_NO = S2.STUDENT_NO)
						where S2.STUDENT_NO = S.STUDENT_NO

							AND T2.UNIV = #{target.univ}


							AND T2.MAJOR = #{target.major}

					)


			order by S.STUDENT_NO DESC
		) A
		where ROWNUM <= #{endRow}
	) B
	where B.RN >= #{startRow}
) C
left join TARGET_INFO T on(T.STUDENT_NO = C.STUDENT_NO)
order by C.RN ASC, T.RANKING ASC

select count(distinct S.STUDENT_NO)
from STUDENT S
left join SCHOOL SCH on (S.SCHOOL_CODE = SCH.SCHOOL_CODE)
left join TARGET_INFO T on(T.STUDENT_NO = S.STUDENT_NO)


		AND S.NAME = #{name}


		AND S.GRADE = #{grade}


		AND S.SEMESTER = #{semester}


		AND S.TRACK = #{track}


		AND SCH.NAME = #{schoolName}



			AND T.UNIV = #{target.univ}


			AND T.MAJOR = #{target.major}
